 const q=query.toLowerCase();return rows.filter(row=>{const state=status(row),d=row.data||{};return (folder==='all'||row.folder_id===folder)&&(!outcome||(outcome==='Held'?['Needs review','Blocked','Interrupted'].includes(state):state===outcome))&&(!start||(d.date&&d.date>=start&&d.date<=today))&&(!q||[row.filename,d.invoice_no,d.vendor,row.po].join(' ').toLowerCase().includes(q));});
