 for(const row of known){const month=/^\d{4}-\d{2}-\d{2}$/.test(row.data.date||'')?row.data.date.slice(0,7):'No date';if(!buckets.has(month))buckets.set(month,{approved:0,pending:0});buckets.get(month)[row.accepted?'approved':'pending']+=Number(row.data.total);}
