 $('#queue-filter').onchange=e=>{statusFilter=e.target.value;queuePage=0;renderQueue();};
 $('#prev').onclick=()=>{queuePage--;renderQueue();};$('#next').onclick=()=>{queuePage++;renderQueue();};$('#refresh').onclick=()=>refresh().catch(showError);wireRows();wireNav();
