async function approveInvoiceBatch(rows,submit){
 const results=[];for(const row of rows.filter(row=>status(row)==='Ready for approval')){try{await submit(row);results.push({id:row.id,ok:true,label:row.data?.invoice_no||row.filename});}catch(error){results.push({id:row.id,ok:false,label:row.data?.invoice_no||row.filename,error:error.message});}}return results;
}
function beginBulk(rows){
 if(bulkBusy)return;const ready=rows.filter(row=>status(row)==='Ready for approval');if(!ready.length)return;const activeSid=sid;
 modal(`Approve ${ready.length} invoices?`,`<p>Approve the selected invoices in ${esc(snapshot.session.name)}. Each must still pass all checks, including the remaining PO balance. This records approval; it does not make a payment.</p><button class="primary approve-large" id="confirm-bulk">Approve ${ready.length} invoices</button>`);
 $('#confirm-bulk').onclick=async()=>{
  bulkBusy=true;$('#general-dialog').close();bulkResult=`Approving ${ready.length} invoices…`;renderQueue();
  try{
   const results=await approveInvoiceBatch(ready,row=>post(`/sessions/${activeSid}/invoices/${row.id}/approve`,{expected_run:row.run}));
   const failed=results.filter(r=>!r.ok),approved=results.length-failed.length;
   bulkResult=`${approved} approved. ${failed.length} could not be approved.`;selectedInvoices.clear();overviewRows=null;
   await refresh(false);if(page==='queue')renderQueue();else if(page==='dashboard')await loadOverview();announce(bulkResult);
   if(failed.length)modal('Some invoices still need review',`<p>${approved} invoices were approved. These invoices were not approved:</p>${failed.map(r=>`<div class="notice warning"><strong>${esc(r.label)}</strong><p>${esc(r.error)}</p></div>`).join('')}`);
  }catch(error){bulkResult='Approval results could not refresh. Refresh the queue before trying again.';showError(error);}
  finally{bulkBusy=false;if(page==='queue')renderQueue();}
 };
}
