function vendorForm(index){const existing=snapshot.session.master.vendors[index];const v=existing||{id:'vendor-'+crypto.randomUUID().slice(0,8),name:'',gstin:'',status:'approved',aliases:[]};modal(existing?'Edit vendor':'Add a vendor',`<form id="vendor-form"><label>Vendor name<input name="name" required maxlength="150" value="${esc(v.name)}"></label><label>GSTIN as recorded in your master<input name="gstin" maxlength="30" value="${esc(v.gstin)}"></label><label>Vendor status<select name="status"><option value="approved" ${v.status==='approved'?'selected':''}>Approved</option><option value="blocked" ${v.status==='blocked'?'selected':''}>Blocked</option></select></label><label>Recognised aliases (one per line)<textarea name="aliases">${esc(v.aliases.join('\n'))}</textarea></label><p class="micro">Add an alias only after confirming it belongs to this vendor. Future invoices can match the recognised name.</p><p class="error" id="master-error"></p><button class="primary full">Save vendor</button></form>`);$('#vendor-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const updated={...v,name:form.elements.name.value.trim(),gstin:form.elements.gstin.value.trim(),status:form.elements.status.value,aliases:form.elements.aliases.value.split('\n').map(x=>x.trim()).filter(Boolean)};const master=structuredClone(snapshot.session.master);if(existing)master.vendors[index]=updated;else master.vendors.push(updated);try{await saveMaster(master);$('#general-dialog').close();}catch(error){$('#master-error').textContent=error.message;}};}
