 (p.lines.length?p.lines:[{}]).forEach(add);$('#add-po-line').onclick=()=>add({});$('#po-form').onsubmit=async e=>{e.preventDefault();const f=e.target;const updated={...p};for(const k of ['number','vendor_id','total','currency','tax_rate','tax_basis','status'])updated[k]=f.elements[k].value.trim();updated.lines=$$('#po-lines tr').map(tr=>{const line=Object.fromEntries($$('[data-po-line]',tr).map(input=>[input.dataset.poLine,input.value.trim()]));const old=p.lines.find(l=>l.id===tr.dataset.id);return {...old,...line,id:tr.dataset.id,aliases:old?.aliases||[],tax_basis:updated.tax_basis,tax_rate:updated.tax_rate};});const master=structuredClone(snapshot.session.master);if(existing)master.pos[index]=updated;else master.pos.push(updated);try{await saveMaster(master);$('#general-dialog').close();}catch(error){$('#master-error').textContent=error.message;}};
