function renderRules(){const rules=[['Read, with evidence','Gemini extracts the document. If the key, quota or service fails, embedded-text extraction and local OCR take over. Missing values remain empty. Fallback fields require human confirmation.'],['Identify the vendor','Match GSTIN or a recognised vendor name and alias. Conflicting identity needs review. An explicitly blocked vendor blocks approval.'],['Find the right PO','Use the printed reference or a unique item-compatible PO. A selected PO must belong to the same vendor and be open. Ambiguous matches require a reviewer.'],['Reconcile the numbers','Check quantity × unit price, subtotal, and subtotal + tax against total, with ₹1 arithmetic tolerance. Exclusive tax is checked against its stated percentage.'],['Respect remaining authorisation','Approved invoices consume both PO amount and line quantities. Approval rechecks balances atomically, so concurrent reviewers cannot spend the same remaining authorisation.'],['Check price and units','Compare unit prices on a consistent tax basis. Variance above 2% needs review; above 5% is flagged as a high-severity dispute. Units must match; no automatic conversions.'],['Catch duplicates in this folder','An earlier identical document or same vendor, invoice number and amount blocks a repeat. Similar vendor, amount, date and items need review. New folders start independent duplicate history.'],['Leave the final decision to a person','Ready for approval means checks passed, not approved or paid. A reviewer approves separately. Corrections and approvals retain an audit trail.'],['Keep missing and unusual data visible','Required vendor, invoice number, date, currency and total cannot be empty. Only INR invoices are supported by this policy. Future dates and invoices older than 365 days need review.'],['Understand the limits','This version reviews one PO per invoice. It does not validate tax registrations, make payments, convert units, or reliably parse handwritten invoices. Unreadable or unusual layouts remain available for manual review.']];$('#page').innerHTML=heading('Rules','These are the checks Ledger applies. Extraction never decides whether an invoice is approved.')+`<div class="rules-grid">${rules.map((r,i)=>`<section class="card"><span class="rule-no">${String(i+1).padStart(2,'0')}</span><h2>${r[0]}</h2><p>${r[1]}</p></section>`).join('')}</div>`;}
async function route(){
 if(!who)return;
 const hash=location.hash.slice(1)||'dashboard',match=hash.match(/^invoice\/(?:([a-f0-9]{32})\/)?([a-f0-9]{32})$/);
 page=match?'detail':Object.hasOwn(labels,hash)?hash:'dashboard';selected=match?.[2]||null;
 $('#export-excel').textContent='Export Excel';$('#page').classList.toggle('dashboard-page',page==='dashboard');$('#crumb').textContent=labels[page];$$('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===(page==='detail'?'queue':page)));
 $('#sidebar').classList.remove('open');syncSidebar();
 try{
  if(!snapshot)return;
  if(match?.[1]&&match[1]!==sid){const target=await json('/sessions/'+match[1]);sid=match[1];snapshot=target;sessionStorage.setItem('ledger-session',sid);selectedInvoices.clear();bulkResult='';renderSessions();}
  if(page==='detail'){$('#page').innerHTML='<div class="card"><p class="muted">Opening invoice...</p></div>';await renderDetail();}
  else if(page==='dashboard'){renderDashboard();if(overviewRows===null)await loadOverview();}
  else ({queue:renderQueue,upload:renderUpload,master:renderMaster,rules:renderRules})[page]();
 }catch(error){showError(error);$('#page').innerHTML=`<div class="notice error">${esc(error.message)}</div><a href="#queue">Return to the review queue</a>`;}
}
async function refresh(render=true){
 if(!sid)return;snapshot=await json('/sessions/'+sid);const t=totals();$('#queue-count').textContent=t.review+t.blocked+t.ready+t.failed;
 if(render&&page!=='detail'){
  if(page==='queue'){if(document.activeElement?.closest('.filters,.bulk-toolbar'))return;renderQueue();}
  else if(page==='dashboard'){if(document.activeElement?.closest('.overview-filters,.amount-card')||overviewLoading)return;await loadOverview();}
 }
 return snapshot;
}
