  if(!config)config=await json('/config');
  workspaceEpoch++;overviewLoading=false;overviewRows=null;overviewFolder='all';overviewOutcome='';overviewSearch='';overviewDate='all';dashboardFilters={vendor:'',start:'',end:'',min:'',max:'',po:'',currency:'INR'};overviewPage=0;selectedInvoices.clear();
  const result=await post('/demo');await startWorkspace(result.session,'upload');$('#auth-dialog').close();$('#content').focus();
