applyTheme(preference('ledger-theme',window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));syncSidebar();
window.addEventListener('hashchange',route);
setInterval(async()=>{if(!who||!sid||pollBusy||document.hidden)return;if(bulkBusy)return;const needs=snapshot?.invoices.some(r=>['queued','running'].includes(r.execution));if(!needs&&!uploading&&Date.now()-lastPoll<20000)return;pollBusy=true;lastPoll=Date.now();try{const before=selected&&snapshot.invoices.find(r=>r.id===selected);await refresh();const after=selected&&snapshot.invoices.find(r=>r.id===selected);if(page==='detail'&&after&&before?.updated!==after.updated&&!$('#review-form')?.dataset.dirty && !$('#review-form')?.contains(document.activeElement))await renderDetail();}catch(error){console.warn('Refresh interrupted');}finally{pollBusy=false;}},4500);
try{config=await json('/config');await ensureCsrf();try{await startWorkspace();}catch(error){if(!error.message.includes('Sign in or choose'))console.warn('Workspace sign-in required');}}catch(error){showDemoError('The service could not be reached. Check your connection and try the demo again.');}
